def process(loadAllYears) -> pd.DataFrame:
    import pandas as pd

    df = loadAllYears
    out = []
    for c in df.columns:
        s = df[c]
        out.append({
            "column": c,
            "dtype": str(s.dtype),
            "nonNull": int(s.notna().sum()),
            "null": int(s.isna().sum()),
            "distinct": int(s.nunique(dropna=True))
        })
    return pd.DataFrame(out).sort_values("column").reset_index(drop=True)
